public sealed class Order
{
    public static Order Open(CustomerId customer, IReadOnlyList<Line> lines)
    {
        ArgumentNullException.ThrowIfNull(customer);
        if (lines.Count == 0) throw new DomainRuleException("cannot open an empty order");
        return new Order(OrderId.New(), customer, [.. lines], OrderStatus.Draft);
    }

    private Order(OrderId id, CustomerId c, IReadOnlyList<Line> lines, OrderStatus s)
        => (Id, Customer, Lines, Status) = (id, c, lines, s);
}
